def test_describe_instances_with_filters(self, ec2): """DescribeInstances with instance-state-name and tag:Name filters.""" images = ec2.describe_images(Filters=[{"Name": "owner-alias", "Values": ["amazon"]}]) if not images["Images"]: images = ec2.describe_images() ami_id = images["Images"][0]["ImageId"] tag_name = _unique("filter-test")
resp = ec2.run_instances( ImageId=ami_id, InstanceType="t2.micro", MinCount=1, MaxCount=1, TagSpecifications=[ { "ResourceType": "instance", "Tags": [{"Key": "Name", "Value": tag_name}], } ], ) instance_id = resp["Instances"][0]["InstanceId"] try: # Filter by state by_state = ec2.describe_instances( Filters=[{"Name": "instance-state-name", "Values": ["running", "pending"]}] ) all_ids = [i["InstanceId"] for r in by_state["Reservations"] for i in r["Instances"]] assert instance_id in all_ids
# Filter by tag:Name by_tag = ec2.describe_instances(Filters=[{"Name": "tag:Name", "Values": [tag_name]}]) tag_ids = [i["InstanceId"] for r in by_tag["Reservations"] for i in r["Instances"]] assert instance_id in tag_ids finally: > ec2.terminate_instances(InstanceIds=[instance_id])
